// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Apple 登录
	// (POST /v1/auth/apple)
	LoginApple(w http.ResponseWriter, r *http.Request)
	// 退出登录（吊销该刷新令牌）
	// (POST /v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// 运营商一键登录（阿里云号码认证 token）
	// (POST /v1/auth/phone/oneclick)
	LoginPhoneOneClick(w http.ResponseWriter, r *http.Request)
	// 用刷新令牌换新令牌（刷新令牌轮换，旧的立即失效）
	// (POST /v1/auth/refresh)
	RefreshSession(w http.ResponseWriter, r *http.Request)
	// 发送短信验证码
	// (POST /v1/auth/sms/send)
	SendSmsCode(w http.ResponseWriter, r *http.Request)
	// 短信验证码登录（新用户自动注册）
	// (POST /v1/auth/sms/verify)
	VerifySmsCode(w http.ResponseWriter, r *http.Request)
	// 微信登录（OpenSDK 授权 code）
	// (POST /v1/auth/wechat)
	LoginWechat(w http.ResponseWriter, r *http.Request)
	// 我的定时简报
	// (GET /v1/briefing-subscriptions)
	ListSubscriptions(w http.ResponseWriter, r *http.Request)
	// 新建定时简报。超过套餐上限返回 403 quota_exceeded
	// (POST /v1/briefing-subscriptions)
	CreateSubscription(w http.ResponseWriter, r *http.Request)
	// 一句话解析成定时简报草稿（不落库）
	// (POST /v1/briefing-subscriptions/draft)
	DraftSubscription(w http.ResponseWriter, r *http.Request)

	// (DELETE /v1/briefing-subscriptions/{subscriptionId})
	DeleteSubscription(w http.ResponseWriter, r *http.Request, subscriptionId SubscriptionId)

	// (GET /v1/briefing-subscriptions/{subscriptionId})
	GetSubscription(w http.ResponseWriter, r *http.Request, subscriptionId SubscriptionId)

	// (PATCH /v1/briefing-subscriptions/{subscriptionId})
	UpdateSubscription(w http.ResponseWriter, r *http.Request, subscriptionId SubscriptionId)
	// 立即生成一期（预览）。返回任务，进度走 SSE，完成事件带 briefingId
	// (POST /v1/briefing-subscriptions/{subscriptionId}/run)
	RunSubscription(w http.ResponseWriter, r *http.Request, subscriptionId SubscriptionId)
	// 历史简报，新的在前
	// (GET /v1/briefings)
	ListBriefings(w http.ResponseWriter, r *http.Request, params ListBriefingsParams)
	// 今日简报（用户时区的今天，每个订阅最多一期，含完整内容）
	// (GET /v1/briefings/today)
	ListTodayBriefings(w http.ResponseWriter, r *http.Request)

	// (GET /v1/briefings/{briefingId})
	GetBriefing(w http.ResponseWriter, r *http.Request, briefingId BriefingId)
	// 对整期或单条打分（同一对象重复提交以最后一次为准）
	// (PUT /v1/briefings/{briefingId}/feedback)
	PutBriefingFeedback(w http.ResponseWriter, r *http.Request, briefingId BriefingId)
	// 远程配置（按当前用户和设备算好的值）
	// (GET /v1/config)
	GetRemoteConfig(w http.ResponseWriter, r *http.Request, params GetRemoteConfigParams)
	// 内置工具 + 白名单 MCP 连接器，及我的开关和授权状态
	// (GET /v1/connectors)
	ListConnectors(w http.ResponseWriter, r *http.Request)
	// 开关连接器。需要授权而未授权时开启返回 409 auth_required
	// (PATCH /v1/connectors/{connectorId})
	UpdateConnector(w http.ResponseWriter, r *http.Request, connectorId ConnectorId)
	// 解除授权并删除凭证
	// (DELETE /v1/connectors/{connectorId}/authorization)
	RevokeConnector(w http.ResponseWriter, r *http.Request, connectorId ConnectorId)
	// 开始授权。App 用 ASWebAuthenticationSession 打开 authUrl，完成后回调 zeus://oauth?connector={id}&status=ok|error
	// (POST /v1/connectors/{connectorId}/authorize)
	AuthorizeConnector(w http.ResponseWriter, r *http.Request, connectorId ConnectorId)
	// 注册或更新推送设备（APNs token），幂等
	// (POST /v1/devices)
	RegisterDevice(w http.ResponseWriter, r *http.Request)

	// (DELETE /v1/devices/{pushToken})
	UnregisterDevice(w http.ResponseWriter, r *http.Request, pushToken string)
	// 注销账号（硬删除全部数据，不可恢复）
	// (DELETE /v1/me)
	DeleteAccount(w http.ResponseWriter, r *http.Request)
	// 当前用户、套餐与额度
	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)

	// (PATCH /v1/me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// 清空全部记忆（硬删除，向量一起删）
	// (DELETE /v1/memories)
	DeleteAllMemories(w http.ResponseWriter, r *http.Request)

	// (GET /v1/memories)
	ListMemories(w http.ResponseWriter, r *http.Request, params ListMemoriesParams)

	// (DELETE /v1/memories/{memoryId})
	DeleteMemory(w http.ResponseWriter, r *http.Request, memoryId string)

	// (GET /v1/reports)
	ListReports(w http.ResponseWriter, r *http.Request, params ListReportsParams)

	// (DELETE /v1/reports/{reportId})
	DeleteReport(w http.ResponseWriter, r *http.Request, reportId ReportId)

	// (GET /v1/reports/{reportId})
	GetReport(w http.ResponseWriter, r *http.Request, reportId ReportId)
	// 针对报告追问。返回任务，答案以 text_delta 事件流式返回，并追加到报告末尾
	// (POST /v1/reports/{reportId}/followups)
	CreateReportFollowup(w http.ResponseWriter, r *http.Request, reportId ReportId)
	// 报告正文 HTML（App 用 WKWebView 带 Bearer 加载；与 H5 分享页同一模板）
	// (GET /v1/reports/{reportId}/html)
	GetReportHtml(w http.ResponseWriter, r *http.Request, reportId ReportId)
	// PDF 下载地址（短时签名链接）。尚未生成时返回 status=generating，稍后重试
	// (GET /v1/reports/{reportId}/pdf)
	GetReportPdf(w http.ResponseWriter, r *http.Request, reportId ReportId)
	// 生成 H5 分享链接
	// (POST /v1/reports/{reportId}/shares)
	CreateShare(w http.ResponseWriter, r *http.Request, reportId ReportId)
	// 撤销分享，链接立即失效
	// (DELETE /v1/shares/{shareId})
	RevokeShare(w http.ResponseWriter, r *http.Request, shareId string)

	// (GET /v1/tasks)
	ListTasks(w http.ResponseWriter, r *http.Request, params ListTasksParams)
	// 发起调研报告。超出本月额度返回 403 quota_exceeded
	// (POST /v1/tasks)
	CreateTask(w http.ResponseWriter, r *http.Request)

	// (GET /v1/tasks/{taskId})
	GetTask(w http.ResponseWriter, r *http.Request, taskId TaskId)
	// 中止任务（已产出内容会尽量收尾保存）
	// (POST /v1/tasks/{taskId}/cancel)
	CancelTask(w http.ResponseWriter, r *http.Request, taskId TaskId)
	// 确认或拒绝一次写操作
	// (POST /v1/tasks/{taskId}/confirmations/{confirmId})
	ResolveConfirmation(w http.ResponseWriter, r *http.Request, taskId TaskId, confirmId string)
	// 任务事件流（SSE）
	// (GET /v1/tasks/{taskId}/events)
	StreamTaskEvents(w http.ResponseWriter, r *http.Request, taskId TaskId, params StreamTaskEventsParams)
	// 运行中补充要求，Agent 在下一步读取
	// (POST /v1/tasks/{taskId}/messages)
	SendTaskMessage(w http.ResponseWriter, r *http.Request, taskId TaskId)
	// 模板列表（官方模板库 / 我的模板）
	// (GET /v1/templates)
	ListTemplates(w http.ResponseWriter, r *http.Request, params ListTemplatesParams)
	// 新建自定义模板（仅自己可见）
	// (POST /v1/templates)
	CreateTemplate(w http.ResponseWriter, r *http.Request)
	// 一句话生成模板草稿（不落库，用户确认后再 createTemplate）
	// (POST /v1/templates/draft)
	DraftTemplate(w http.ResponseWriter, r *http.Request)

	// (DELETE /v1/templates/{templateId})
	DeleteTemplate(w http.ResponseWriter, r *http.Request, templateId TemplateId)

	// (GET /v1/templates/{templateId})
	GetTemplate(w http.ResponseWriter, r *http.Request, templateId TemplateId)
	// 修改自定义模板（官方模板不可改，可先复制）
	// (PATCH /v1/templates/{templateId})
	UpdateTemplate(w http.ResponseWriter, r *http.Request, templateId TemplateId)
	// 复制模板为我的模板
	// (POST /v1/templates/{templateId}/copy)
	CopyTemplate(w http.ResponseWriter, r *http.Request, templateId TemplateId)
}

